INSERT INTO feature VALUES('diagnostics-ledger','workflow','Diagnostics exemplars','syntax-ledger','partial','ordinary',NULL,'One focused source per refusal name no form qualifies, and per reserved or unadmitted boundary, under `corpus/ledger/diagnostics/`, each refused with its subject and settled by `check:exemplars`; a name without one is a row of the gate''s owed table, with the reason no source reaches it or the issue writing it. A recovery sweep, `ledger recovery`, writes each literal tile of each syntax exemplar as its near miss and deletes it, and reports each mutant whose first error marks other bytes than the mutation; the nightly run files each cause, a first error and mutation kind, on one issue.','workflow-ledger-tasks surface-corpus','corpus/ledger/diagnostics',NULL,'#1782 #1788 #1789');
